package com.srent.dispute; import com.srent.common.BaseEntity; import com.srent.user.User; import jakarta.persistence.*; import lombok.*;
@Entity @Table(name="dispute_evidence") @Getter @Setter @NoArgsConstructor public class DisputeEvidence extends BaseEntity{@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="dispute_id",nullable=false)private Dispute dispute;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="uploaded_by",nullable=false)private User uploadedBy;@Column(name="object_key",nullable=false,unique=true)private String objectKey;@Column(name="content_type",nullable=false)private String contentType;}
